#include <torch/extension.h>
#include <ATen/Dispatch.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <stdint.h>

// Scalar path: fp32 sigmoid math for all scalar types, matching the source contract.
template <typename scalar_t>
__global__ void swiglu_scalar_kernel(const scalar_t* __restrict__ x,
                                     scalar_t* __restrict__ y,
                                     int64_t N, int64_t D) {
    int64_t row = (int64_t)blockIdx.x;
    int64_t col = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    if (row >= N || col >= D) return;

    const scalar_t* __restrict__ x_row = x + row * (2 * D);
    scalar_t* __restrict__ y_row = y + row * D;

    float gate = static_cast<float>(x_row[col]);
    float up   = static_cast<float>(x_row[col + D]);
    float silu = gate / (1.0f + expf(-gate));
    y_row[col] = static_cast<scalar_t>(silu * up);
}

// fp16 vector path. Used only when D is even, so gate/up/y row addresses are half2 aligned.
__global__ void swiglu_half2_kernel(const half* __restrict__ x,
                                    half* __restrict__ y,
                                    int64_t N, int64_t D2) {
    int64_t row = (int64_t)blockIdx.x;
    int64_t col2 = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    if (row >= N || col2 >= D2) return;

    int64_t D = D2 * 2;
    const half* __restrict__ x_row = x + row * (2 * D);
    half* __restrict__ y_row = y + row * D;

    const half2* __restrict__ gate2_ptr = reinterpret_cast<const half2*>(x_row);
    const half2* __restrict__ up2_ptr   = reinterpret_cast<const half2*>(x_row + D);
    half2* __restrict__ y2_ptr          = reinterpret_cast<half2*>(y_row);

    half2 g2 = gate2_ptr[col2];
    half2 u2 = up2_ptr[col2];
    float2 g = __half22float2(g2);
    float2 u = __half22float2(u2);

    float r0 = (g.x / (1.0f + expf(-g.x))) * u.x;
    float r1 = (g.y / (1.0f + expf(-g.y))) * u.y;
    y2_ptr[col2] = __float22half2_rn(make_float2(r0, r1));
}

void swiglu_forward(torch::Tensor x, torch::Tensor y) {
    const int64_t N = x.size(0);
    const int64_t D = y.size(1);
    if (N == 0 || D == 0) return;

    constexpr int threads = 256;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (x.scalar_type() == at::ScalarType::Half && (D % 2 == 0)) {
        dim3 grid((unsigned int)N, (unsigned int)((D / 2 + threads - 1) / threads));
        swiglu_half2_kernel<<<grid, threads, 0, stream>>>(
            reinterpret_cast<const half*>(x.data_ptr<at::Half>()),
            reinterpret_cast<half*>(y.data_ptr<at::Half>()),
            N, D / 2);
        return;
